INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '物体に働く「力のつりあい」について、間違いはどれか。', '["力がつりあっているとき、物体の運動状態は変化しない","力がつりあっているとき、合力は0である","力がつりあっているとき、必ず2つの力である","力がつりあっているとき、物体は静止しているか等速直線運動をしている"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '運動方程式はベクトル形式で F = ma と書ける。この式の物理的な意味はどれか。', '["力と加速度は同じ向きである","力と加速度は逆向きである","力は加速度の2乗に比例する","質量は力と加速度の両方に影響する"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '質量mの物体が高さhまで持ち上げられたとき、物体が得る重力による位置エネルギーを表す式はどれか。ただし、重力加速度の大きさをgとする。', '["mgh","mg/h","mgh^2","mg/h^2"]', 0, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '質量m、速さvで運動する物体の運動エネルギーを表す式はどれか。', '["mv","mv^2","1/2mv","1/2mv^2"]', 3, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '仕事率の単位として正しいものはどれか。', '["J (ジュール)","W (ワット)","N (ニュートン)","N/m"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '力学的エネルギー保存の法則が成り立つための条件として最も適切なものはどれか。', '["摩擦力や抵抗力が働かないとき","物体に働く外力が0のとき","運動エネルギーが一定のとき","位置エネルギーが0のとき"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '物体が移動する距離をd、その方向に加えた力をFとするとき、物体がされた仕事Wを表す式はどれか。', '["W = F + d","W = F / d","W = F * d","W = F / d^2"]', 2, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'ある一定の仕事をするのにかかる時間が半分になった場合、仕事率は何倍になるか。', '["1/2倍","同じ","2倍","4倍"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '高さhから物体を自然落下させたとき、落下途中のある点での運動エネルギーと位置エネルギーの和（力学的エネルギー）はどうなるか。', '["減少する","増加する","一定である","0になる"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'バネ定数kのバネを自然長からxだけ引き伸ばしたとき、蓄えられる弾性エネルギーはどれか。', '["kx","kx^2","1/2kx","1/2kx^2"]', 3, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '力学的エネルギーの単位である「J (ジュール)」を基本単位で表すとどれか。', '["kg・m/s","kg・m/s^2","kg・m^2/s^2","kg・m^2/s"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '仕事率P、時間t、仕事Wの関係式として正しいものはどれか。', '["P = Wt","P = W/t","P = t/W","P = W - t"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '質量mの物体を静かに滑り台から滑らせたとき、斜面を滑り降りる際に力学的エネルギーが保存される仮定で、最下点での速さvを求める式はどれか（hはスタート時の高さ）。', '["v = hg","v = 2gh","v = sqrt(gh)","v = sqrt(2gh)"]', 3, 3);
