INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '速さが2倍になると、運動エネルギーは何倍になるか。', '["√2倍","2倍","4倍","8倍"]', 2, 2);
