INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '仕事率1Wとは、どのような状態を指すか。', '["1秒間に1Jの仕事をする割合","1分間に1Jの仕事をする割合","1秒間に1Nの力を加える割合","1秒間に1m移動させる割合"]', 0, 2);
