INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '高さhの位置にある物体が持つエネルギーの基準（0点）はどこに設定してもよい。基準を物体の高さより高い位置に設定した場合、位置エネルギーの符号はどうなるか。', '["常に正","常に負","常に0","基準の取り方によらない"]', 1, 3);
