INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '摩擦のある面を物体が移動するとき、発生する熱エネルギーと力学的エネルギーの関係として正しいものはどれか。', '["力学的エネルギーは保存される","力学的エネルギーは増加する","減少した力学的エネルギーは熱エネルギーに変換される","熱エネルギーは力学的エネルギーに完全に変換される"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '物体に加える力と移動距離のグラフにおいて、囲まれた面積は何を表すか。', '["仕事率","運動エネルギー","位置エネルギー","仕事"]', 3, 2);
