INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '物体が一定の速さで上昇しているとき、その物体の力学的エネルギーはどう変化しているか。', '["増加している","減少している","一定である","0である"]', 0, 2);
