INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '銀 Ag が希硝酸には溶けるが、希塩酸には溶けない理由は何か。', '["銀の方が水素よりイオン化傾向が大きいから","銀は酸化力が非常に強いから","銀のイオン化傾向が水素より小さく、硝酸の酸化力が働いているから","希塩酸と反応して不溶性の塩を作るから"]', 2, 3);
