INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'ハロゲン単体の色の組み合わせとして正しいものはどれか。', '["フッ素：淡黄色、塩素：黄緑色、臭素：赤褐色、ヨウ素：黒紫色","フッ素：淡黄色、塩素：赤褐色、臭素：黄緑色、ヨウ素：黒紫色","フッ素：無色、塩素：淡黄色、臭素：赤褐色、ヨウ素：紫黒色","フッ素：淡黄色、塩素：黄緑色、臭素：暗赤色、ヨウ素：紫色"]', 0, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'フッ化水素酸(HF)の特徴として適切な記述はどれか。', '["弱酸性であり、ガラスを溶かす性質はない。","強酸性であり、ガラスを溶かす性質がある。","弱酸性であるが、ガラスを溶かす性質がある。","強酸性であり、ガラスを溶かす性質はない。"]', 2, 2);
