INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '硫黄の同素体のうち、常温で最も安定なものはどれか。', '["斜方硫黄","単斜硫黄","ゴム状硫黄","非晶質硫黄"]', 0, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '濃硫酸の性質として誤っているものはどれか。', '["吸湿性がある","脱水作用がある","酸化作用がある","揮発性が高い"]', 3, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '二酸化硫黄(SO2)が還元剤として働く反応式のうち、正しいものはどれか。', '["SO2 + 2H2O → SO4^2- + 4H^+ + 2e^-","SO2 + 4H^+ + 4e^- → S + 2H2O","SO2 + 2H2S → 3S + 2H2O","SO2 + O2 → 2SO3"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '窒素の固定に関連する記述として正しいものはどれか。', '["工業的にはハーバー・ボッシュ法でアンモニアを合成する。","窒素は非常に反応しやすく、常温で酸素と化合する。","硝酸はアンモニアの酸化によって直接得られる。","オストワルト法で窒素から硝酸を製造する。"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'オストワルト法による硝酸製造の各段階において、触媒として白金が用いられる工程はどこか。', '["窒素と水素の反応","アンモニアの酸化","一酸化窒素の酸化","二酸化窒素の吸収"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'リンの同素体である赤リンと黄リンの性質の比較として正しいものはどれか。', '["両者とも水に溶けやすく、猛毒である。","黄リンは空気中で自然発火しやすいため、水中に保存する。","赤リンは黄リンよりも反応性が高く、毒性が強い。","赤リンは暗所で発光する性質がある。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '炭素の同素体であるダイヤモンドと黒鉛の性質についての記述として、誤っているものはどれか。', '["ダイヤモンドは共有結合結晶で、電気を通さない。","黒鉛は層状構造を持ち、層間ではファンデルワールス力で結ばれている。","黒鉛は電気伝導性を持つ。","ダイヤモンドは黒鉛よりも密度が小さい。"]', 3, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'ケイ素(Si)の性質および化合物に関する記述として正しいものはどれか。', '["二酸化ケイ素は水に溶けてケイ酸になる。","ケイ酸ナトリウム水溶液は水ガラスと呼ばれ、酸を加えるとケイ酸ゲルを生じる。","ケイ素は金属元素である。","二酸化ケイ素は常温で気体である。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'アルカリ金属（1族元素）の性質として、誤っているものはどれか。', '["いずれも水と激しく反応し、水素を発生する。","炎色反応を示す。","密度が大きく、融点が高い。","空気中で容易に酸化される。"]', 2, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '炭酸ナトリウム(Na2CO3)の工業的製法は何か。', '["ハーバー・ボッシュ法","オストワルト法","アンモニアソーダ法（ソルベー法）","接触法"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'アルカリ土類金属（2族元素）の性質に関する記述として、最も適切なものはどれか。', '["カルシウムは冷水と反応しない。","バリウムは炎色反応が赤色である。","カルシウムイオンを含む水溶液に硫酸イオンを加えると、沈殿が生じる。","マグネシウムはアルカリ土類金属に含まれる。"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'アルミニウムの性質として正しいものはどれか。', '["両性金属であり、酸とも塩基とも反応して水素を発生する。","不動態を形成しやすく、濃硝酸には激しく反応する。","アルミニウムはイオン化傾向が小さいため、自然界では単体で見つかる。","水酸化アルミニウムは水に溶けやすい。"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '鉄(Fe)に関する記述として、誤っているものはどれか。', '["赤血球のヘモグロビンの成分である。","希硫酸に溶けて水素を発生する。","濃硝酸を加えると不動態となり、それ以上反応が進まなくなる。","鉄(Ⅲ)イオンはヘキサシアニド鉄(Ⅱ)酸カリウム水溶液と反応して濃青色沈殿（紺青）を生じる。"]', 3, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '銅(Cu)の反応に関する記述として正しいものはどれか。', '["銅は希硫酸に溶けて水素を発生する。","銅を濃硝酸に溶かすと、一酸化窒素が発生する。","銅イオンを含む水溶液にアンモニア水を少量加えると、深青色の溶液になる。","銅イオンを含む水溶液に硫化水素を通すと、黒色の沈殿が生じる。"]', 3, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '銀(Ag)およびその化合物に関する記述として、正しいものはどれか。', '["塩化銀は水に溶けやすい。","硝酸銀水溶液に塩酸を加えると、白濁が生じる。","銀は希硫酸に溶けて水素を発生する。","酸化銀は黒色である。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', '亜鉛(Zn)の性質として、適切なものはどれか。', '["両性金属ではない。","水酸化亜鉛は水酸化ナトリウム水溶液に溶けない。","亜鉛イオンは硫化水素と反応して、白色沈殿を生じる。","亜鉛は強塩基には反応しない。"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'クロム(Cr)の化合物に関する記述として正しいものはどれか。', '["クロム酸イオン(CrO4^2-)は黄色である。","二クロム酸イオン(Cr2O7^2-)は還元剤として働く。","クロムの化合物はすべて人体に無害である。","クロム酸カリウム水溶液は酸性で橙色になる。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'science', 'マンガン(Mn)の化合物である過マンガン酸カリウム(KMnO4)の性質として、誤っているものはどれか。', '["酸性条件下では無色のMn^2+になる。","中性・塩基性条件下では褐色のMnO2になる。","酸化剤として働く。","過マンガン酸カリウム溶液は黄色である。"]', 3, 3);
