INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '1970年代のデタントを象徴する、米ソによる制限条約は何か。', '["SALT I","START","INF","NPT"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '1968年、チェコスロバキアで発生した自由化運動を何と呼ぶか。', '["プラハの春","ハンガリー動乱","連帯革命","ビロード革命"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '日本国憲法が定める「国民主権」の理念に基づき、国権の最高機関とされているのはどれか。', '["内閣","最高裁判所","国会","天皇"]', 2, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「法の下の平等」を規定した憲法第14条に関する記述として、最も適切なものはどれか。', '["すべての国民の社会的地位の完全な平等を保障している。","人種、信条、性別、社会的身分または門地による差別を禁止している。","経済的な格差を是正するために、累進課税の導入を義務付けている。","すべての国民に対して、同等の教育を受ける権利を直接的に保障している。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '日本国憲法において「基本的人権」の性質として最も適切に説明しているものはどれか。', '["国民が国家から恩恵として与えられる権利。","国会が法律によって定めた範囲内で認められる権利。","侵すことのできない永久の権利として保障されている権利。","公共の福祉に反しない限りにおいてのみ認められる限定的な権利。"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '日本国憲法が規定する「政教分離の原則」の目的として、最も適切なものはどれか。', '["宗教団体が政治活動を行うことを全面的に禁止するため。","国家と特定の宗教との結びつきを避け、信教の自由を保障するため。","学校教育における宗教教育を排除するために設けられた規定。","政治家が個人の信仰を持つことを制限するため。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「憲法改正」の手続きとして、日本国憲法第96条に規定されている条件はどれか。', '["各議院の総議員の過半数の賛成が必要。","各議院の総議員の3分の2以上の賛成と、国民投票による過半数の賛成が必要。","両院協議会での合意と、天皇の認証が必要。","衆議院の3分の2以上の賛成と、最高裁判所の違憲審査が必要。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '裁判所が持つ権限の一つであり、法律や処分が憲法に適合するかを審査する権限を何というか。', '["司法権の独立","違憲審査制","弾劾裁判権","適正手続きの保障"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「精神的自由権」に分類されないものはどれか。', '["思想・良心の自由","信教の自由","居住・移転の自由","表現の自由"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「生存権」を規定した日本国憲法第25条に関連する訴訟として、最も有名なものはどれか。', '["堀木訴訟","家永教科書訴訟","三菱樹脂事件","青い芝の会訴訟"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '三権分立の仕組みにおいて、国会が内閣に対して行使できる権限はどれか。', '["解散権","違憲審査権","内閣不信任決議権","予算案の提出権"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '日本国憲法第13条「個人の尊重」に基づき、近年重要視されている「プライバシーの権利」に関連する考え方はどれか。', '["知る権利","自己決定権","環境権","団結権"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「刑事手続き上の権利」として、憲法第37条などで保障されていないものはどれか。', '["迅速な公開裁判を受ける権利","証人への反対尋問権","弁護人を依頼する権利","黙秘権の放棄"]', 3, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「法の支配」の概念を最もよく説明しているものはどれか。', '["権力者が法を制定し、国民を統治すること。","法が権力を拘束し、権力の濫用を防ぐこと。","どのような法であれ、制定された法には絶対に従うこと。","裁判所が全ての行政権を掌握し、法を執行すること。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「公共の福祉」による人権制限について、最も適切な説明はどれか。', '["人権は公共の福祉のためであれば、いつでも制限される。","公共の福祉とは、国民全員の総意のことである。","人権相互の衝突を調整するための実質的な公平の原理である。","国家が公共の福祉を名目に、憲法を停止することを認めるもの。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '日本国憲法における「天皇の地位」に関する記述として正しいものはどれか。', '["日本国および日本国民統合の象徴であり、国政に関する権能を有する。","主権者であり、国民の代表として政治を指導する。","日本国および日本国民統合の象徴であり、国政に関する権能は有しない。","大日本帝国憲法と同様に、統治権の総攬者である。"]', 2, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '最高裁判所裁判官の国民審査制度において、罷免される条件はどれか。', '["投票者の過半数の賛成があった場合。","投票者の過半数が「やめさせるべき」と票を投じた場合。","投票数が有権者の半数に満たない場合。","国会の3分の2以上の決議があった場合。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「表現の自由」に関する説明として誤っているものはどれか。', '["検閲は、絶対的に禁止されている。","事前の抑制は、いかなる場合も認められない。","公共の福祉による制限を受けることがある。","通信の秘密は、表現の自由を支える前提条件の一つである。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '衆議院の優越が認められている事項として、正しいものはどれか。', '["法律案の議決","条約の承認","予算の議決","憲法改正の発議"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '日本国憲法第21条が保障する「表現の自由」には含まれないとされる概念はどれか。', '["知る権利","取材の自由","報道の自由","営利目的の宣伝の自由"]', 3, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「適正手続きの保障」を定めた憲法第31条は何を意味するか。', '["法に基づいていれば、どのような刑罰も科すことができる。","法律の定める手続きによらなければ、生命や自由を奪われない。","裁判を受ける権利は、いかなる時も制限されない。","警察官は、裁判所の令状なしにいつでも逮捕できる。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「経済的自由権」に分類されるものはどれか。', '["職業選択の自由","学問の自由","幸福追求権","請願権"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '内閣が国会に対して負う責任を何というか。', '["天皇への報告責任","裁判所への法的責任","連帯して国会に対する責任","政党に対する政治責任"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '国会議員が「不逮捕特権」を持つ理由として、最も適切なものはどれか。', '["法律を制定する権利を守るため。","国会活動を不当な公権力から守り、その機能を保障するため。","議員個人を法律の適用から除外するため。","有権者から選ばれた代表者であることを示すため。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '憲法第14条の「法の下の平等」に関連して、差別を禁止する根拠となるものはどれか。', '["個人の尊厳","公共の福祉","三権分立","国民主権"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「参政権」に含まれないものはどれか。', '["選挙権","最高裁判所裁判官の国民審査権","公務員を選定・罷免する権利","請願権"]', 3, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '違憲審査において、裁判所はどのような手続きで審査を行うか。', '["裁判所が自発的に、制定された法律すべてを憲法審査する。","国会からの要請があった場合のみ、法律を審査する。","個別の具体的な訴訟事件を前提として審査する（付随的違憲審査制）。","内閣の諮問に応じて、法律の合憲性を判断する。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「勤労の権利」および「労働三権」に関連して、正しいものはどれか。', '["労働三権には、団結権、団体交渉権、団体行動権が含まれる。","労働三権は、公務員には一切認められていない。","勤労の権利は、国家がすべての人に職場を提供することを義務付けている。","労働三権は、日本国憲法において「基本的人権」に含まれないとされている。"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '憲法第20条で保障される「信教の自由」に含まれない活動はどれか。', '["特定の宗教を信仰すること。","宗教的な行事に参加しないこと。","宗教団体が政治的な目的で特定の政党を支援すること。","宗教教育を学校で行うこと（公立学校を除く）。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '日本国憲法が「最高法規」であることの根拠はどれか。', '["憲法を制定したのが天皇であるから。","憲法に反する法律等は効力を有しないと規定されているから。","憲法は他の法律よりも改正手続きが簡単であるから。","国会が最高機関であることの付随的な結果であるから。"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「学問の自由」の説明として最も適切なものはどれか。', '["大学教授の研究活動は、いかなる制限も受けない。","学問的研究の成果を公表する自由は含まれるが、教授の自由は含まれない。","大学の自治は、学問の自由を保障するための制度的保障である。","国は、学問の研究方針を決定し指示する権限を有する。"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '両院協議会において、衆議院と参議院の意見が一致しなかった場合に優先されるルールについて、正しいものはどれか。', '["原則として参議院の意思が優先される。","原則として衆議院の意思が優先される（法律案の場合）。","両院の議長が最終決定を下す。","必ず国民投票を行って決定する。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '憲法第15条の「公務員を選定・罷免する権利」が意味するものはどれか。', '["国民が公務員の給与を直接決定する権利。","国民が公務員に対して懲戒処分を下す権利。","国民が投票によって、公務員を選択・解職する権利。","公務員は国民の公僕であることを確認する権利。"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「社会権」の性格として適切なものはどれか。', '["国家による自由（国家からの自由）。","国家による自由（国家への自由）。","国家による自由（国家を通じての自由）。","国家による自由（国家との自由）。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '三権分立のうち、「司法権の独立」を保障している制度はどれか。', '["裁判官の身分保障（心身の故障などによる罷免以外は免職されない）。","国会が裁判官の判決を修正できる制度。","内閣が裁判官を自由に任命できる権限。","最高裁判所が内閣の解散権を停止できる権限。"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '国会の召集に関して、正しいものはどれか。', '["国会は、毎年1回召集される通常国会のみが開催される。","天皇は、内閣の助言と承認により国会を召集する。","衆議院の解散中であっても、参議院の緊急集会は開かれない。","国会召集は裁判所の決定に基づき行われる。"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '日本国憲法において「基本的人権」の保障に関する規定のうち、絶対的に侵すことのできないとされているのはどれか。', '["身体の自由","公共の福祉のための制限","個人の尊重（第13条の「生命、自由および幸福追求に対する国民の権利」）","経済活動の自由"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '需要曲線と供給曲線が交わる点で決定される価格を何と呼ぶか。', '["均衡価格","独占価格","管理価格","再販売価格"]', 0, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '価格が均衡価格よりも高い水準にある場合、市場ではどのような状態が生じるか。', '["超過供給","超過需要","市場均衡","市場の失敗"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', 'ある財の価格が上昇したとき、その代替財の需要量は一般的にどう変化するか。', '["増加する","減少する","変化しない","ゼロになる"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '価格が変化しても需要量がほとんど変化しない性質を何と呼ぶか。', '["需要の価格弾力性が小さい","需要の価格弾力性が大きい","供給の価格弾力性が小さい","供給の価格弾力性が大きい"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '企業が生産量を増やしても、ある地点から効率が低下することを何というか。', '["収穫逓減の法則","収穫逓増の法則","規模の経済","範囲の経済"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '物価が持続的に上昇し、貨幣価値が下落する現象を何というか。', '["インフレーション","デフレーション","スタグフレーション","リフレーション"]', 0, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '不況下で物価が上昇する現象を指す言葉はどれか。', '["スタグフレーション","ハイパーインフレーション","デフレスパイラル","コストプッシュ・インフレ"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '「ディマンド・プル・インフレ」の原因として適切なものはどれか。', '["総需要の過度な増加","原材料価格の高騰","賃金上昇によるコスト増","供給力の著しい低下"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', 'デフレーションが進行することで、企業の売上が減り、賃金が下がる悪循環を何と呼ぶか。', '["デフレスパイラル","流動性の罠","負の乗数効果","合成の誤謬"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '家計が将来の不安から消費を控え、貯蓄を増やすことで景気が悪化する現象を何というか。', '["合成の誤謬","逆選択","モラルハザード","情報の非対称性"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '中央銀行が市場の通貨供給量を増やすことで景気を刺激する政策は何か。', '["金融緩和政策","金融引き締め政策","財政出動","増税政策"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '完全競争市場の条件として「情報の完全性」以外に挙げられるものはどれか。', '["多数の売り手と買い手","政府による価格統制","製品の差別化","参入障壁の存在"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'social_studies', '独占禁止法に基づき、公正な競争を阻害する行為を監視する機関はどこか。', '["公正取引委員会","金融庁","経済産業省","財務省"]', 0, 2);
