INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '評論において「客観性」を担保するために必要な態度はどれか。', '["自分の感情を優先して結論を導き出すこと","証拠や論理に基づき、第三者が検証可能な形で主張すること","特定の特殊なケースを一般論として押し付けること","抽象的な概念を避け、具体的なエピソードのみを語ること"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「主観」が排除された記述の例として適切なものはどれか。', '["私にはこの景色がとても悲しく見える","この出来事は絶対に悪いことだと断言できる","会議には5人の参加者がいたという記録がある","美しいものには必ず何らかの法則が隠れている"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「具体」と「抽象」の関係性について、正しい記述はどれか。', '["具体は抽象の結果であり、抽象は具体の要因である","具体と抽象は全く無関係な二つの領域である","具体は細部を伴う個別の事象であり、抽象はそれらを統合した概念である","抽象のみが真実であり、具体は幻想に過ぎない"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「普遍的な真理」とは、どのような性質を持つものを指すか。', '["時代や場所が変わっても変わらず成立する論理や法則","その時の感情や感覚によって変化する個人的な見解","ある特定の地域でのみ有効とされる生活の知恵","具体的な数値で表現された一時的な調査結果"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「特殊」という言葉が持つニュアンスとして不適切なものはどれか。', '["例外的であること","一般的であること","限られた範囲であること","個性的であること"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '抽象度の高い文章とは、どのような文章か。', '["具体的な実例が豊富で、情景が目に浮かびやすい文章","概念や理論などの大きな枠組みで議論が進む文章","著者の個人的な思い出話が中心となっている文章","日常会話に近い言葉遣いで綴られた親しみやすい文章"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '筆者が「抽象的な議論」をした後に「具体的な事例」を出す目的は何か。', '["議論の内容をあえて曖昧にして、読者の想像力を高めるため","抽象概念を読者に分かりやすく理解させるため","論理の整合性を無視して、感情に訴えかけるため","普遍性を否定し、特殊な事実を強調するため"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「客観的視点」を持つために最も重要なことはどれか。', '["自分自身の考えを絶対的な正解とみなすこと","他者の意見や論理を、自己の立場と切り離して公平に扱うこと","抽象的な理論を捨てて、具体的なエピソードのみを追求すること","歴史的な背景を無視して、現代の価値観だけで判断すること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「普遍」の対義語の組み合わせとして、最も適切なものはどれか。', '["抽象と具体","主観と客観","特殊と個別","普遍と特殊"]', 3, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「主観的」であることの利点と欠点の説明として適切なものはどれか。', '["論理的である反面、人間味に欠ける","感情的で説得力がある反面、一般性に欠ける","客観的すぎて、読者が理解しにくい","普遍性が高すぎて、個別のケースに応用できない"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「概念化」は、どの操作に近いか。', '["具体化","抽象化","主観化","特殊化"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '次のうち、「抽象化」の反対の動作はどれか。', '["一般化","具体化","要約化","概念化"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「主観」の説明として最も適切なものはどれか。', '["観察者自身の価値観や感情を投影した捉え方","誰にとっても間違いのない数学的な証明","社会的に合意された、変わることのない事実","ある対象を外側から冷静に分析する態度"]', 0, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「普遍性がある」という言葉の意味として正しいものはどれか。', '["特定の集団内だけで通じる秘密である","誰にでも当てはまる性質を持っている","一過性のブームである","個人の好き嫌いに左右されるものである"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '文章構成において「具体例を提示する」際の効果は何か。', '["読者の理解を助け、抽象概念に肉付けを与える","論理をより抽象的で難解なものにする","著者の個人的な願望を強調する","普遍的な理論を破棄して特殊化する"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '客観的な記述を目指す際に避けるべきものはどれか。', '["明確な根拠やデータ","個人的な感情に基づく断定","論理的な一貫性","誰もが検証可能な事実"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「普遍的な妥当性」とはどのような状態を指すか。', '["特殊な環境下でのみ一時的に認められる状態","いつでもどこでも誰に対しても有効であると認められる状態","著者の主観によってのみ正当化される状態","抽象的すぎて誰にも理解できない状態"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「抽象的」という言葉が批判的に使われる場合、どのような意味を持つことが多いか。', '["本質を鋭く突いている","具体的すぎて退屈である","実体を伴わず、漠然としていて分かりにくい","個人の思い入れが強すぎる"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「特殊」という言葉が持つ論理的な役割は何か。', '["普遍的なルールに当てはまらないケースを特定する","物事をすべて同じカテゴリーに分類する","抽象度を上げて理解を容易にする","個人の主観を客観に変換する"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「主観」と「客観」の対比について、誤っている説明はどれか。', '["主観は自己、客観は他者や外部世界を意識する","主観は感情を伴いやすく、客観は論理を伴いやすい","主観は普遍性を追求し、客観は特殊性を追求する","主観は個人的な視点、客観は共有可能な視点である"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「具体」から「抽象」へと思考を巡らせることを何と呼ぶか。', '["帰納的アプローチ","演繹的アプローチ","主観的解釈","特殊化のプロセス"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「普遍」の対義語として不適切なものはどれか。', '["特殊","個別","限定的","抽象"]', 3, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「具体」という言葉が持つ性質として適切なものはどれか。', '["概念的で、範囲が広い","個別の事象で、範囲が限定的である","常に主観的な判断に依存する","議論を抽象化するために不可欠である"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '評論読解において「客観化」するとはどういうことか。', '["自分の主張を他人のせいにすること","自分の感情を排し、対象を第三者の立場で捉え直すこと","難しい言葉を使って読者を煙に巻くこと","具体例をすべて省略して理論だけを語ること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「抽象度を上げる」とは、どういう操作を指すか。', '["より細かな具体例を付け加えること","個々の事例から共通の枠組みを見出し、一般化すること","自分の個人的な経験を強く主張すること","客観的な事実を個人の感情に変えること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「普遍と特殊」の対比において、以下の文中の空欄に入る言葉は？『人間は死ぬという事実は（A）であり、この私が今日死ぬかどうかは（B）である。』', '["A:特殊 B:普遍","A:具体 B:抽象","A:普遍 B:特殊","A:主観 B:客観"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「抽象と具体」を往復する文章の書き方として、最も論理的な構成はどれか。', '["具体例だけを羅列し、最後に抽象的な概念でまとめる","抽象的な主張を行い、具体的な事例でそれを補強・説明する","抽象的な主張を繰り返すだけで、最後まで具体的な事例を出さない","個人の主観的なエピソードだけを語り、普遍的な結論を避ける"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「いそいそと出かける」の「いそいそ」が表す心情として最も適切なものはどれか。', '["不安で落ち着かない様子","期待に胸を膨らませて楽しげな様子","急いでいて焦っている様子","義務感で仕方なく動く様子"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「しょんぼりと肩を落とす」の「しょんぼり」が表す心情として最も適切なものはどれか。', '["誇らしく自信に満ちた様子","活気に溢れて騒がしい様子","元気がなく、力落とししている様子","考え込み、一点を見つめる様子"]', 2, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「うっとり」という語が持つニュアンスとして最も適切なものはどれか。', '["強い怒りで震えている状態","美しさや快さに心を奪われている状態","周囲の騒音にイライラしている状態","強い恐怖で動けなくなっている状態"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「じれったい」が表す感情として最も適切なものはどれか。', '["自分の思い通りにならず、もどかしい気持ち","相手に対して強い親近感を抱く気持ち","物事の結果を静かに待つ余裕がある気持ち","深い悲しみに打ちひしがれる気持ち"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「ふてぶてしい」態度の説明として最も適切なものはどれか。', '["相手を過度に敬う卑屈な態度","図太く、開き直っているような生意気な態度","繊細で傷つきやすい臆病な態度","常に周囲に気を配りすぎる態度"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「おどおど」と「びくびく」の共通点として適切なものはどれか。', '["自分に自信があり、堂々としていること","恐怖や不安を感じて落ち着かないこと","周囲に対して攻撃的であること","無関心で冷淡であること"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「すげない」態度とはどのようなものか。', '["愛想がなく、冷淡なこと","情熱的で相手を求めること","非常に親切で世話好きなこと","混乱して支離滅裂なこと"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「やきもき」する心情の説明として最も適切なものはどれか。', '["深い満足感に浸っている様子","思い通りにいかず、じれったく心配な様子","退屈で眠気を感じている様子","嫉妬心を隠して笑っている様子"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「しおらしい」態度とはどのような様子か。', '["強気で相手を威圧する様子","謙虚で、控えめでおとなしい様子","派手で目立とうとする様子","強情で妥協しない様子"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「うらぶれた」様子の解説として適切なものはどれか。', '["華やかで勢いがある様子","落ちぶれて、みすぼらしい様子","隠し事をして緊張している様子","健康で活気に満ちた様子"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「たじろぐ」という動作が示唆する心情はどれか。', '["相手の勢いに押されてひるむ気持ち","積極的に議論に参加したい意欲","相手を見下して軽蔑する気持ち","心から同意して従う気持ち"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「そっけない」返事とはどのようなものか。', '["内容が詳しく、相手を気遣うもの","愛想がなく、冷淡で無関心なもの","感情が高ぶり、涙を流すもの","冗談を交えて笑わせるもの"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「あくせく」働くとは、どのような心情・態度か。', '["ゆとりを持って楽しむこと","目先のことに追われて、余裕がないこと","将来の計画を立てて準備すること","他人に指示を出して管理すること"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「気後れ」するとはどのような状態か。', '["相手と対等に渡り合おうとすること","相手の雰囲気や実力に圧倒されて自信を失うこと","強引に自分の意見を押し通すこと","相手の動向を冷ややかに観察すること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「腑に落ちない」とはどのような状態を指すか。', '["納得できず、しっくりこないこと","非常に驚いて言葉を失うこと","深く感動して涙を流すこと","強い怒りを隠していること"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「鼻にかける」という慣用句の正しい意味はどれか。', '["匂いに敏感になること","自慢して得意になること","相手を馬鹿にすること","体調を崩すこと"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「やりきれない」心情として適切なものはどれか。', '["幸福感で満たされている","堪えがたいほど不快や悲しみに満ちている","非常にやる気に満ちている","何も感じず、無感動である"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「さばさばした」性格の説明として最も適切なものはどれか。', '["こだわりが強く、根に持つこと","執着心がなく、さっぱりとしていること","計算高く、損得を考えること","優柔不断で決断できないこと"]', 1, 1);
