INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「けなげ」という評価が示す態度はどれか。', '["ずる賢くて油断できないこと","弱者が一生懸命に頑張る様子","傲慢で高飛車な様子","甘やかされて育った様子"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「あやふや」な態度とはどのようなものか。', '["はっきりせず、不確かなこと","非常に真剣で誠実なこと","論理的で分かりやすいこと","強い決意に満ちていること"]', 0, 1);
