INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「すねる」態度の心理として適切なものはどれか。', '["素直になれず、意地を張って不機嫌になる","相手に好かれようと愛想を振りまく","自分のミスを正直に認める","物事に無関心を装う"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「身につまされる」とはどのような心情か。', '["自分の身に引き寄せて、切実な思いを感じること","他人事として興味を失うこと","誰かに非難されて恥ずかしく思うこと","身体の疲れが極限に達すること"]', 0, 3);
