INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '実用的な文章において「指示語」が指し示す内容を特定する際、最も留意すべき点は何か。', '["文章全体の筆者の主張を要約する","指示語の直前または直後の文との論理的なつながりを確認する","辞書的な意味に基づき、一般的な用法のみを考慮する","指示語が使われている文の主語と述語のみを分析する"]', 1, 1);
