INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '対話文形式の読解において、発話者が「補足説明」をしている箇所を見抜くための手がかりはどれか。', '["「つまり」「すなわち」といった言い換えの接続詞","「しかし」「だが」といった逆接の接続詞","「なぜなら」という理由を述べる接続詞","「一方で」という対比を示す接続詞"]', 0, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', 'アンケート集計結果のグラフと文章の整合性を確認する際、不適切な推論はどれか。', '["グラフの数値の変化を文章中で引用している","グラフの数値を基に、文章中で個人の感想を事実として述べている","グラフの項目と文章中の主題が合致している","グラフが示す傾向を文章で論理的に説明している"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '複数の資料（ポスターとメモなど）を比較する問題で、情報の「網羅性」を確認する際の考え方はどれか。', '["すべての資料に同じ情報が重複して記載されていることを確認する","各資料で役割分担されており、必要な情報が漏れなく提示されているか確認する","最も情報量の多い資料のみを優先的に読む","文字数の少ない資料を優先的に無視する"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', 'メール文の推敲において、依頼の丁寧さを高めるための工夫として正しいものはどれか。', '["「～してください」という命令形を使用する","「お忙しいところ恐縮ですが」といったクッション言葉を添える","箇条書きを使用せず、すべて文章で長々と述べる","相手の名前を省略して親近感を出す"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '対話文の中で、一方が「反論」を述べている箇所を特定する方法として適切なものはどれか。', '["相手の意見を肯定する同意表現に注目する","相手の主張に対して「～という見方もできますが」と切り出す箇所に注目する","話題を全く別の内容に転換する箇所に注目する","単に相手の言葉を繰り返している箇所に注目する"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「文章の構成」を問う問題において、段落の役割として不適切なものはどれか。', '["一つのまとまった話題（トピック）を展開する","前後の文脈をつなぐための架け橋となる","筆者の感情を無秩序に並べる","文末表現を統一し、読みやすさを高める"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '共通テストの実用文でよく問われる「目的に応じた適切な表現の選択」において、最も重視される視点はどれか。', '["自身の語彙力を最大限に誇示する","対象となる読者が誰であり、どのような文脈で読まれるかを考慮する","できる限り専門用語を多用して権威付けする","主観的な感想を極力多く盛り込む"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '議事録の要約として、最も情報が正確に保持されているものはどれか。', '["参加者の発言をすべて時系列順に書き写したもの","主要な決定事項と、その背景にある議論の要点を整理したもの","参加者の個人の雑談を詳しく記録したもの","司会者の個人的な主観を強調してまとめたもの"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', 'マニュアル（説明書）の文章において、誤解を防ぐための記述として適切なものはどれか。', '["「だいたい」「そこそこ」といった曖昧な副詞を多用する","手順を番号順に並べ、一文を短く簡潔にする","専門家しか理解できない隠語を用いる","比喩表現を用いて親しみやすさを強調する"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '対話文で示された「提案」に対する「条件」を確認する際、注意すべき点はどれか。', '["提案者側のメリットのみを抽出する","「～という条件であれば可能」「～が必要」といった制約事項を確認する","相手の個人的な都合を推測して解釈する","議論の内容を無視して自分の意見を押し通す"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', 'Webサイトのトップページと下層ページの関係性において、適切な記述はどれか。', '["トップページには詳細なデータのみを記載し、下層ページで要約する","トップページで全体像を示し、下層ページで詳細情報を提示する","どちらにも同じ内容を重複して記載することで強調する","下層ページには何もリンクを貼らないことで迷わせない"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '文章の推敲で「接続詞の選択」を問う問題において、逆接の接続詞が必要なケースはどれか。', '["前文で述べたことと、同じ結論を導く場合","前文で述べたことと、対照的な事実を述べる場合","前文で述べたことの、具体的な例を挙げる場合","前文で述べたことの、結論を言い換える場合"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', 'ある団体の規約（実用文）で「禁止事項」を列挙する際、最も重要な構成はどれか。', '["読者が読み飛ばさないよう、文末に小さく記載する","何をしてはいけないのか、具体的に明記する","禁止の理由だけを書き、具体的な行為は曖昧にする","すべての項目を一つながりの長い文章にする"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '報告書の作成において、「事実」と「意見」を区別するメリットはどれか。', '["文章の文字数を効率的に増やすことができるから","事実に基づいた客観的な評価と、筆者の主観的な判断を読み手に明確に伝えるため","事実を隠して意見のみを伝えることがビジネスの常識だから","文法的な整合性をとるためだけの形式的な作業だから"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '学校行事のポスターにおいて、情報を「優先順位」付けする際の基準はどれか。', '["文字のフォントの種類を揃えること","日時・場所・内容など、参加に必要な必須情報を目立たせること","筆者の個性を表すデザインを優先すること","情報を極力減らして余白を多くすること"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '対話文において、話し手が「合意に至る」までのプロセスとして不適切なものはどれか。', '["お互いの主張を整理する","妥協点を見出す","自分の意見のみを繰り返す","共通の目的を確認する"]', 2, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '推敲のプロセスにおいて「呼応関係」を確認する際、チェックすべき箇所はどれか。', '["「決して～ない」「まるで～ようだ」といった文のねじれがないか","漢字の書き間違いがないか","主語と述語の距離がどれだけ離れているか","段落の数が適切かどうか"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「条件付きの要約」問題において、求められている要件はどれか。', '["指定された文字数と、盛り込むべきキーワードをすべて満たすこと","自分の創造性を発揮して全く新しいストーリーを作成すること","筆者の考えを完全に無視して個人的な批判を展開すること","できるだけ長く、格調高い表現を用いること"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '案内文における「敬語」の使い方の妥当性について、適切なものはどれか。', '["顧客に対して過度な二重敬語を多用する","関係者同士の通知であれば、敬語を一切使わず命令形で良い","相手や状況に合わせて、適切な敬語を選択し丁寧さを保つ","尊敬語と謙譲語を意図的に入れ替えて親近感を出そうとする"]', 2, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '複数の資料から「必要な情報を抽出する」力とは、何を指すか。', '["すべての資料を隅から隅まで暗記すること","問いの目的に合わせ、関連する情報のみを選択的に読み取ること","資料に書かれていない情報を推測して創作すること","文字数の多い資料を優先して評価すること"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '文章表現において、文が「冗長（長すぎる）」であると判断される要因はどれか。', '["必要な情報を簡潔にまとめすぎている","不要な修飾語や同じ意味の言葉が繰り返されている","論理的な構成が明確である","文の終わりに丁寧語が使われている"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '対話形式の読解で、話し手が「話題を転換」する際のサインとなる表現はどれか。', '["「なるほど」","「ところで」「話は変わりますが」","「つまり」","「したがって」"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', 'グラフや表を用いた文章問題で、誤った解釈の例として適切なものはどれか。', '["グラフの凡例を確認してデータの項目を特定する","グラフの縦軸の単位を無視して数値の大小を比較する","文章中に記載されたデータの背景にある意図を考察する","表の行と列が示す意味を正確に読み解く"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '広報誌や校内掲示板で、読み手に「最も注意を惹きつける」ための工夫はどれか。', '["冒頭に大きなタイトルや、核心的な情報を配置する","すべての情報を同じフォントサイズで均一に書く","関係のない個人的な思い出話から書き始める","専門家しか知らないマニアックな話題から入る"]', 0, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '推敲の段階で「文のねじれ」を直す修正例として、正しいものはどれか。', '["「私の願いは、将来は医者になりたい」→「私の願いは、将来医者になることだ」","「今日は雨が降った」→「今日は雨が降りました」","「彼は走る」→「彼は速く走る」","「それは難しい」→「それは非常に難しい」"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', 'メールの件名において、最も適切な工夫はどれか。', '["「お世話になっております」とだけ書く","「重要」などの言葉を並べて相手を急かす","内容が簡潔に伝わる具体的な件名にする","何も書かずに送ることで興味を引く"]', 2, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '資料を比較して「矛盾点」を探す際、有効な手順はどれか。', '["一つの資料だけを熟読する","両方の資料に共通して書かれている箇所と、食い違っている箇所を整理する","直感的にどちらが正しいか決める","文字数が多い資料を正しいと判断する"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '議事録で「決定事項」を明確にするために欠かせない項目はどれか。', '["参加者全員の当日の服装","検討された課題、出された意見、そして最終的に決まったこと","会議中に話題になった世間話","会議が行われた場所の周辺地図"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '文章全体の「構成案（プロット）」を作成する際、まず考えるべきことは何か。', '["最初の一文の美しさ","論理の展開の順序と、何をどの順で説明するか","使用する修辞技法の種類","文字数の正確な見積もり"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '対話文の中で、話し手が「相手の意見を尊重している」ことがわかる表現はどれか。', '["「それはおかしいですね」","「なるほど、そういう考え方もありますね」","「それには反対です」","「話を聞いていませんでした」"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', '「実用文」の定義として、最も適当なものはどれか。', '["個人の空想や感情を綴った随筆","日常生活の課題解決や情報共有を目的とした文章","抽象的な概念のみを論じた哲学的な著作","韻律やリズムを重視した詩歌"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'japanese', 'レポート作成において「引用」を行う際、守るべきマナーはどれか。', '["引用元を明記し、引用した箇所を明確に区別する","自分の意見としてそのまま書き写す","引用した内容を大幅に改変して独自の理論にする","引用元を一切明かさずに自分の知識として発表する"]', 0, 2);
